// spec: specs/session-auth.md (1.3) · кейс SA-06 · запасной путь (MCP playwright-test отключён)
// seed: tests/seed.parent-b.spec.ts (только чтобы взять публичный apikey; сами запросы — без токена пользователя)
import { test, expect } from '@playwright/test';
import { NONEXISTENT_CHILD, PARENT_B, captureSupabase, rest } from './session-auth.helpers';

test.use({ storageState: PARENT_B });

test.describe('Сессия и права — API', () => {
  test('anon (только apikey): RPC и таблицы ребёнка → 401 permission denied @desktop @prod-safe #a337fd', async ({ page, request }) => {
    const sb = await captureSupabase(page, '/children');
    const anon = { apikey: sb.apikey }; // без authorization

    const calls = [
      { name: 'rpc/current_levels', method: 'POST', path: '/rest/v1/rpc/current_levels', body: { p_child_id: NONEXISTENT_CHILD } },
      { name: 'rpc/child_profile', method: 'POST', path: '/rest/v1/rpc/child_profile', body: { p_child_id: NONEXISTENT_CHILD } },
      { name: 'rpc/has_gate_pin', method: 'POST', path: '/rest/v1/rpc/has_gate_pin', body: {} },
      { name: 'children', method: 'GET', path: '/rest/v1/children?select=*&limit=5' },
    ] as const;

    for (const c of calls) {
      const r = await rest(request, sb.base, anon, c.method, c.path, 'body' in c ? c.body : undefined);
      // «Все RPC закрыты для неавторизованного (anon)» — комментарий программиста к #a337fd
      expect(r.status, `${c.name}: ${r.text}`).toBe(401);
      expect(JSON.parse(r.text).message, c.name).toMatch(/^permission denied/);
    }
  });
});
